+		return m
+	}
+	en := load("en.json")
+	files, err := localeFS.ReadDir("locales")
+	if err != nil {
+		t.Fatal(err)
+	}
+	for _, f := range files {
+		locale := load(f.Name())
+		for key := range en {
+			if _, ok := locale[key]; !ok {
+				t.Errorf("%s: missing key %q", f.Name(), key)
+			}
+		}
+	}
